     1→/**
     2→ * Dashboard Screen
     3→ *
     4→ * Main screen showing real-time workout metrics including power,
     5→ * heart rate, cadence, speed, distance, and calories.
     6→ *
     7→ * Features:
     8→ * - Responsive grid layout that adapts to portrait/landscape orientations
     9→ * - Connection status indicator in the header
    10→ * - Real-time metrics from metricsStore
    11→ * - Power zone color coding
    12→ */
    13→
    14→import React, { useMemo } from 'react';
    15→import {
    16→  StyleSheet,
    17→  Text,
    18→  View,
    19→  ScrollView,
    20→  useWindowDimensions,
    21→  RefreshControl,
    22→} from 'react-native';
    23→import { SafeAreaView } from 'react-native-safe-area-context';
    24→import type { MainTabScreenProps } from '@/navigation/types';
    25→import { useTheme } from '@/theme';
    26→import { MetricCard, ConnectionStatus, PowerDisplay, HeartRateDisplay } from '@/components';
    27→import { useConnectionStore, selectConnectionStatus, selectCurrentServer } from '@/stores/connectionStore';
    28→import {
    29→  useMetricsStore,
    30→  selectCurrentPower,
    31→  selectPower3sAvg,
    32→  selectHeartRate,
    33→  selectHeartRateMax,
    34→  selectCadence,
    35→  selectSpeed,
    36→  selectDistance,
    37→  selectCalories,
    38→  selectTargetPower,
    39→  selectTargetCadence,
    40→  getPowerZone,
    41→  getHeartRateZone,
    42→} from '@/stores/metricsStore';
    43→import { useSessionStore, selectIsSessionActive } from '@/stores/sessionStore';
    44→
    45→/**
    46→ * Orientation type for layout calculations
    47→ */
    48→type Orientation = 'portrait' | 'landscape';
    49→
    50→/**
    51→ * Grid configuration based on orientation
    52→ */
    53→interface GridConfig {
    54→  columns: number;
    55→  powerCardSpan: 'full' | 'half';
    56→  gap: number;
    57→}
    58→
    59→/**
    60→ * Get grid configuration based on screen dimensions
    61→ */
    62→function getGridConfig(width: number, height: number): GridConfig {
    63→  const orientation: Orientation = width > height ? 'landscape' : 'portrait';
    64→
    65→  if (orientation === 'landscape') {
    66→    return {
    67→      columns: 4,
    68→      powerCardSpan: 'half',
    69→      gap: 12,
    70→    };
    71→  }
    72→
    73→  return {
    74→    columns: 2,
    75→    powerCardSpan: 'full',
    76→    gap: 12,
    77→  };
    78→}
    79→
    80→/**
    81→ * Format elapsed time as HH:MM:SS
    82→ */
    83→function formatElapsedTime(seconds: number): string {
    84→  const hours = Math.floor(seconds / 3600);
    85→  const minutes = Math.floor((seconds % 3600) / 60);
    86→  const secs = Math.floor(seconds % 60);
    87→
    88→  if (hours > 0) {
    89→    return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    90→  }
    91→  return `${minutes}:${secs.toString().padStart(2, '0')}`;
    92→}
    93→
    94→/**
    95→ * Format distance with appropriate precision
    96→ */
    97→function formatDistance(km: number): string {
    98→  if (km < 10) {
    99→    return km.toFixed(2);
   100→  }
   101→  if (km < 100) {
   102→    return km.toFixed(1);
   103→  }
   104→  return km.toFixed(0);
   105→}
   106→
   107→/**
   108→ * Default FTP for zone calculations (should come from user settings)
   109→ * TODO: Get from user settings when available
   110→ */
   111→const DEFAULT_FTP = 200;
   112→
   113→/**
   114→ * Default max HR for zone calculations (should come from user settings)
   115→ * TODO: Get from user settings when available
   116→ */
   117→const DEFAULT_MAX_HR = 185;
   118→
   119→type Props = MainTabScreenProps<'Dashboard'>;
   120→
   121→export function DashboardScreen(_props: Props): React.JSX.Element {
   122→  const { colors, spacing, typography, borderRadius } = useTheme();
   123→  const { width, height } = useWindowDimensions();
   124→
   125→  // Connection state
   126→  const connectionStatus = useConnectionStore(selectConnectionStatus);
   127→  const currentServer = useConnectionStore(selectCurrentServer);
   128→
   129→  // Session state
   130→  const isSessionActive = useSessionStore(selectIsSessionActive);
   131→  const elapsedSecs = useSessionStore(state => state.elapsedSecs);
   132→
   133→  // Metrics state
   134→  const power = useMetricsStore(selectCurrentPower);
   135→  const power3sAvg = useMetricsStore(selectPower3sAvg);
   136→  const heartRate = useMetricsStore(selectHeartRate);
   137→  const heartRateMax = useMetricsStore(selectHeartRateMax);
   138→  const cadence = useMetricsStore(selectCadence);
   139→  const speed = useMetricsStore(selectSpeed);
   140→  const distance = useMetricsStore(selectDistance);
   141→  const calories = useMetricsStore(selectCalories);
   142→  const targetPower = useMetricsStore(selectTargetPower);
   143→  const targetCadence = useMetricsStore(selectTargetCadence);
   144→
   145→  // Calculate grid configuration
   146→  const gridConfig = useMemo(() => getGridConfig(width, height), [width, height]);
   147→
   148→  // Calculate power zone
   149→  const powerZone = useMemo(() => getPowerZone(power, DEFAULT_FTP), [power]);
   150→
   151→  // Calculate HR zone
   152→  const hrZone = useMemo(
   153→    () => (heartRate ? getHeartRateZone(heartRate, DEFAULT_MAX_HR) : null),
   154→    [heartRate]
   155→  );
   156→
   157→  // Determine if we're connected and can show metrics
   158→  const isConnected = connectionStatus === 'connected' || connectionStatus === 'authenticated';
   159→  const showMetrics = isConnected && isSessionActive;
   160→
   161→  // Server name for status display
   162→  const serverName = currentServer
   163→    ? `${currentServer.name || currentServer.host}:${currentServer.port}`
   164→    : undefined;
   165→
   166→  // Calculate card widths based on grid columns
   167→  const cardWidth = useMemo(() => {
   168→    const totalGap = (gridConfig.columns - 1) * gridConfig.gap;
   169→    const padding = spacing.md * 2;
   170→    const availableWidth = width - padding - totalGap;
   171→    return availableWidth / gridConfig.columns;
   172→  }, [width, gridConfig, spacing.md]);
   173→
   174→  // Power card width (full width in portrait, half in landscape)
   175→  const powerCardWidth = useMemo(() => {
   176→    if (gridConfig.powerCardSpan === 'full') {
   177→      return width - spacing.md * 2;
   178→    }
   179→    return cardWidth * 2 + gridConfig.gap;
   180→  }, [gridConfig, cardWidth, width, spacing.md]);
   181→
   182→  return (
   183→    <SafeAreaView
   184→      style={[styles.container, { backgroundColor: colors.background }]}
   185→      edges={['top']}
   186→    >
   187→      {/* Header with title and connection status */}
   188→      <View style={[styles.header, { paddingHorizontal: spacing.md }]}>
   189→        <Text style={[styles.title, typography.textStyles.screenTitle, { color: colors.textPrimary }]}>
   190→          Dashboard
   191→        </Text>
   192→        <ConnectionStatus
   193→          status={connectionStatus}
   194→          variant="badge"
   195→          animated
   196→          serverName={serverName}
   197→        />
   198→      </View>
   199→
   200→      <ScrollView
   201→        style={styles.scrollView}
   202→        contentContainerStyle={[
   203→          styles.content,
   204→          { padding: spacing.md, gap: gridConfig.gap },
   205→        ]}
   206→        showsVerticalScrollIndicator={false}
   207→        refreshControl={
   208→          <RefreshControl
   209→            refreshing={false}
   210→            onRefresh={() => {
   211→              // Could trigger a metrics refresh here
   212→            }}
   213→            tintColor={colors.accent}
   214→          />
   215→        }
   216→      >
   217→        {/* Metrics Grid */}
   218→        <View style={[styles.metricsGrid, { gap: gridConfig.gap }]}>
   219→          {/* Power Display - Primary metric with zone indicator */}
   220→          <PowerDisplay
   221→            power={power}
   222→            power3sAvg={power3sAvg}
   223→            powerZone={powerZone}
   224→            targetPower={targetPower}
   225→            showMetrics={showMetrics}
   226→            style={{ width: powerCardWidth }}
   227→          />
   228→
   229→          {/* Heart Rate Display - with zone indicator and pulse animation */}
   230→          <HeartRateDisplay
   231→            heartRate={heartRate}
   232→            hrZone={hrZone}
   233→            maxHeartRate={heartRateMax}
   234→            showMetrics={showMetrics}
   235→            showPulseAnimation={showMetrics}
   236→            style={{ width: cardWidth }}
   237→          />
   238→
   239→          {/* Cadence */}
   240→          <MetricCard
   241→            value={showMetrics && cadence ? cadence : '--'}
   242→            unit="rpm"
   243→            label="Cadence"
   244→            size="medium"
   245→            targetValue={targetCadence ?? undefined}
   246→            targetLabel="Target"
   247→            accentColor={
   248→              showMetrics && targetCadence && cadence
   249→                ? Math.abs(cadence - targetCadence) > 10
   250→                  ? colors.warning
   251→                  : colors.success
   252→                : undefined
   253→            }
   254→            style={{ width: cardWidth }}
   255→            accessibilityLabel={`Cadence: ${showMetrics && cadence ? cadence : 'no data'} revolutions per minute`}
   256→/>
   257→
   258→          {/* Speed */}
   259→          <MetricCard
   260→            value={showMetrics ? speed.toFixed(1) : '--'}
   261→            unit="km/h"
   262→            label="Speed"
   263→            size="medium"
   264→            style={{ width: cardWidth }}
   265→            accessibilityLabel={`Speed: ${showMetrics ? speed.toFixed(1) : 'no data'} kilometers per hour`}
   266→          />
   267→
   268→          {/* Distance */}
   269→          <MetricCard
   270→            value={showMetrics ? formatDistance(distance) : '0.00'}
   271→            unit="km"
   272→            label="Distance"
