     1→/**
     2→ * Button Component
     3→ *
     4→ * Customizable button with multiple variants and sizes.
     5→ * Supports primary, secondary, outline, and danger variants.
     6→ */
     7→
     8→import React, { useCallback } from 'react';
     9→import {
    10→  Pressable,
    11→  Text,
    12→  StyleSheet,
    13→  ViewStyle,
    14→  TextStyle,
    15→  PressableProps,
    16→  ActivityIndicator,
    17→} from 'react-native';
    18→import { useTheme } from '@/theme';
    19→
    20→/**
    21→ * Button variants
    22→ */
    23→export type ButtonVariant = 'primary' | 'secondary' | 'outline' | 'danger' | 'ghost';
    24→
    25→/**
    26→ * Button sizes
    27→ */
    28→export type ButtonSize = 'small' | 'medium' | 'large';
    29→
    30→/**
    31→ * Button props
    32→ */
    33→export interface ButtonProps extends Omit<PressableProps, 'style'> {
    34→  /** Button text */
    35→  title: string;
    36→  /** Button variant */
    37→  variant?: ButtonVariant;
    38→  /** Button size */
    39→  size?: ButtonSize;
    40→  /** Whether the button is in a loading state */
    41→  loading?: boolean;
    42→  /** Whether the button takes full width */
    43→  fullWidth?: boolean;
    44→  /** Custom container style */
    45→  style?: ViewStyle;
    46→  /** Custom text style */
    47→  textStyle?: TextStyle;
    48→  /** Left icon element */
    49→  leftIcon?: React.ReactNode;
    50→  /** Right icon element */
    51→  rightIcon?: React.ReactNode;
    52→}
    53→
    54→/**
    55→ * Button Component
    56→ *
    57→ * A customizable button component with multiple variants for different actions.
    58→ *
    59→ * @example
    60→ * ```tsx
    61→ * <Button
    62→ *   title="Pause Workout"
    63→ *   variant="primary"
    64→ *   onPress={() => handlePause()}
    65→ * />
    66→ * ```
    67→ */
    68→export function Button({
    69→  title,
    70→  variant = 'primary',
    71→  size = 'medium',
    72→  loading = false,
    73→  fullWidth = false,
    74→  disabled,
    75→  style,
    76→  textStyle,
    77→  leftIcon,
    78→  rightIcon,
    79→  onPress,
    80→  ...pressableProps
    81→}: ButtonProps): React.JSX.Element {
    82→  const { colors, spacing, typography, borderRadius: themeRadius } = useTheme();
    83→
    84→  // Get variant-specific colors
    85→  const variantColors = getVariantColors(variant, colors);
    86→
    87→  // Get size-specific styles
    88→  const sizeStyles = getSizeStyles(size, spacing, typography);
    89→
    90→  // Handle press with loading state
    91→  const handlePress = useCallback(
    92→    (event: Parameters<NonNullable<PressableProps['onPress']>>[0]) => {
    93→      if (!loading && onPress) {
    94→        onPress(event);
    95→      }
    96→    },
    97→    [loading, onPress],
    98→  );
    99→
   100→  // Dynamic button style
   101→  const getButtonStyle = ({ pressed }: { pressed: boolean }): ViewStyle => {
   102→    const baseStyle: ViewStyle = {
   103→      flexDirection: 'row',
   104→      alignItems: 'center',
   105→      justifyContent: 'center',
   106→      borderRadius: themeRadius.sm,
   107→      paddingHorizontal: sizeStyles.paddingHorizontal,
   108→      paddingVertical: sizeStyles.paddingVertical,
   109→      backgroundColor: variantColors.background,
   110→      borderWidth: variant === 'outline' ? 1 : 0,
   111→      borderColor: variant === 'outline' ? variantColors.border : undefined,
   112→      opacity: disabled || loading ? 0.5 : 1,
   113→      ...(fullWidth ? { width: '100%' } : {}),
   114→    };
   115→
   116→    // Apply pressed state
   117→    if (pressed && !disabled && !loading) {
   118→      baseStyle.backgroundColor = variantColors.backgroundPressed;
   119→    }
   120→
   121→    return baseStyle;
   122→  };
   123→
   124→  // Accessibility props
   125→  const accessibilityLabel = pressableProps.accessibilityLabel || title;
   126→  const accessibilityHint = loading
   127→    ? 'Button is loading'
   128→    : disabled
   129→      ? 'Button is disabled'
   130→      : undefined;
   131→
   132→  return (
   133→    <Pressable
   134→      style={({ pressed }) => [getButtonStyle({ pressed }), style]}
   135→      onPress={handlePress}
   136→      disabled={disabled || loading}
   137→      accessibilityRole="button"
   138→      accessibilityLabel={accessibilityLabel}
   139→      accessibilityHint={accessibilityHint}
   140→      accessibilityState={{
   141→        disabled: disabled || loading,
   142→        busy: loading,
   143→      }}
   144→      {...pressableProps}
   145→    >
   146→      {loading ? (
   147→        <ActivityIndicator
   148→          size="small"
   149→          color={variantColors.text}
   150→          style={styles.loadingIndicator}
   151→        />
   152→      ) : (
   153→        <>
   154→          {leftIcon && <>{leftIcon}</>}
   155→          <Text
   156→            style={[
   157→              styles.text,
   158→              sizeStyles.text,
   159→              { color: variantColors.text },
   160→              leftIcon ? styles.textWithLeftIcon : undefined,
   161→              rightIcon ? styles.textWithRightIcon : undefined,
   162→              textStyle,
   163→            ]}
   164→            numberOfLines={1}
   165→          >
   166→            {title}
   167→          </Text>
   168→          {rightIcon && <>{rightIcon}</>}
   169→        </>
   170→      )}
   171→    </Pressable>
   172→  );
   173→}
   174→
   175→/**
   176→ * Get variant-specific colors
   177→ */
   178→function getVariantColors(
   179→  variant: ButtonVariant,
   180→  colors: ReturnType<typeof useTheme>['colors'],
   181→) {
   182→  switch (variant) {
   183→    case 'primary':
   184→      return {
   185→        background: colors.accent,
   186→        backgroundPressed: colors.accentDark,
   187→        text: colors.textInverse,
   188→        border: colors.accent,
   189→      };
   190→    case 'secondary':
   191→      return {
   192→        background: colors.surface,
   193→        backgroundPressed: colors.elevated,
   194→        text: colors.textPrimary,
   195→        border: colors.border,
   196→      };
   197→    case 'outline':
   198→      return {
   199→        background: 'transparent',
   200→        backgroundPressed: colors.surface,
   201→        text: colors.accent,
   202→        border: colors.accent,
   203→      };
   204→    case 'danger':
   205→      return {
   206→        background: colors.error,
   207→        backgroundPressed: '#B02020',
   208→        text: colors.textInverse,
   209→        border: colors.error,
   210→      };
   211→    case 'ghost':
   212→      return {
   213→        background: 'transparent',
   214→        backgroundPressed: colors.surface,
   215→        text: colors.textPrimary,
   216→        border: 'transparent',
   217→      };
   218→  }
   219→}
   220→
   221→/**
   222→ * Get size-specific styles
   223→ */
   224→function getSizeStyles(
   225→  size: ButtonSize,
   226→  spacing: ReturnType<typeof useTheme>['spacing'],
   227→  typography: ReturnType<typeof useTheme>['typography'],
   228→) {
   229→  const { textStyles } = typography;
   230→  switch (size) {
   231→    case 'large':
   232→      return {
   233→        paddingHorizontal: spacing.xl,
   234→        paddingVertical: spacing.lg,
   235→        text: {
   236→          ...textStyles.button,
   237→          fontSize: 18,
   238→        },
   239→      };
   240→    case 'medium':
   241→      return {
   242→        paddingHorizontal: spacing.lg,
   243→        paddingVertical: spacing.md,
   244→        text: textStyles.button,
   245→      };
   246→    case 'small':
   247→      return {
   248→        paddingHorizontal: spacing.md,
   249→        paddingVertical: spacing.sm,
   250→        text: textStyles.buttonSmall,
   251→      };
   252→  }
   253→}
   254→
   255→const styles = StyleSheet.create({
   256→  text: {
   257→    textAlign: 'center',
   258→  },
   259→  textWithLeftIcon: {
   260→    marginLeft: 8,
   261→  },
   262→  textWithRightIcon: {
   263→    marginRight: 8,
   264→  },
   265→  loadingIndicator: {
   266→    marginVertical: 2,
   267→  },
   268→});
