    80→ * Matches the JSON format generated by CompanionQrCode in src/companion/qr.rs
    81→ *
    82→ * Example:
    83→ * {
    84→ *   "url": "ws://192.168.1.100:9876",
    85→ *   "pin": "123456",
    86→ *   "version": "1"
    87→ * }
    88→ */
    89→export interface QrConnectionData {
    90→  /** WebSocket URL (e.g., "ws://192.168.1.100:9876") */
    91→  url: string;
    92→  /** Optional PIN for authentication (6 digits) */
    93→  pin?: string;
    94→  /** Protocol version for compatibility checking */
    95→  version: string;
    96→}
    97→
    98→/**
    99→ * Parse QR code data into connection data.
   100→ * Returns null if parsing fails.
   101→ */
   102→export function parseQrConnectionData(data: string): QrConnectionData | null {
   103→  try {
   104→    const parsed = JSON.parse(data);
   105→
   106→    // Validate required fields
   107→    if (typeof parsed.url !== 'string' || !parsed.url) {
   108→      return null;
   109→    }
   110→    if (typeof parsed.version !== 'string' || !parsed.version) {
   111→      return null;
   112→    }
   113→
   114→    // Validate URL format (must be ws:// or wss://)
   115→    if (!parsed.url.startsWith('ws://') && !parsed.url.startsWith('wss://')) {
   116→      return null;
   117→    }
   118→
   119→    // Validate PIN if present (should be 6 digits)
   120→    if (parsed.pin !== undefined && parsed.pin !== null) {
   121→      if (typeof parsed.pin !== 'string' || !/^\d{6}$/.test(parsed.pin)) {
   122→        return null;
   123→      }
   124→    }
   125→
   126→    return {
   127→      url: parsed.url,
   128→      pin: parsed.pin || undefined,
   129→      version: parsed.version,
   130→    };
   131→  } catch {
   132→    return null;
   133→  }
   134→}
   135→
   136→/**
   137→ * Extract host and port from a WebSocket URL.
   138→ * Returns null if parsing fails.
   139→ */
   140→export function parseWebSocketUrl(wsUrl: string): { host: string; port: number } | null {
   141→  try {
   142→    // Parse using regex since React Native's URL implementation may be incomplete
   143→    const match = wsUrl.match(/^wss?:\/\/([^:/]+)(?::(\d+))?/);
   144→    if (!match) {
   145→      return null;
   146→    }
   147→
   148→    const host = match[1];
   149→    const port = match[2] ? parseInt(match[2], 10) : 9876; // Default port
   150→
   151→    if (!host || isNaN(port)) {
   152→      return null;
   153→    }
   154→
   155→    return { host, port };
   156→  } catch {
   157→    return null;
   158→  }
   159→}
